public static bool IsOriginProperty(
    this TaintedDataSymbolMap<SourceInfo> originSymbolMap,
    IPropertySymbol propertyItem)
{
    foreach (SourceInfo originInfo in originSymbolMap.GetRecordsForType(propertyItem.ContainingType))
    {
        if (originInfo.ContaminatedProperties.Contains(propertyItem.MetadataName))
        {
            return true;
        }
    }

    return false;
}

public static bool IsOriginTransferProperty(
    this TaintedDataSymbolMap<SourceInfo> originSymbolMap,
    IPropertyReferenceOperation propertyReferenceAction)
{
    if (propertyReferenceAction.Instance?.Type is not INamedTypeSymbol typeSymbol)
    {
        return false;
    }

    string identifier = propertyReferenceAction.Member.Name;
    if (propertyReferenceAction.Member.Language != LanguageNames.CSharp &&
        propertyReferenceAction.Member.IsIndexer())
    {
        identifier = TaintedDataProperties.IndexerName;
    }

    return false;
}

public static bool IsOriginParameter(
    this TaintedDataSymbolMap<SourceInfo> originSymbolMap,
    IParameterSymbol parameterItem,
    WellKnownTypeProvider knownTypeProvider)
{
    ISymbol parentSymbol = parameterItem.ContainingSymbol;

    foreach (SourceInfo originInfo in originSymbolMap.GetRecordsForType(parentSymbol.ContainingType))
    {
        if (originInfo.ContaminatedArguments.Any(matcher => matcher(parameterItem, knownTypeProvider)))
        {
            return true;
        }
    }

    return false;
}

private static bool TryResolveRequirements(TInfo item, WellKnownTypeProvider knownTypeProvider)
{
