public override PropertySetAbstractValue Merge(PropertySetAbstractValue valA, PropertySetAbstractValue valB)
{
    int maximumKnownCount = Math.Max(valA.KnownValuesCount, valB.KnownValuesCount);
    using var _ = ArrayBuilder<PropertySetAbstractValueKind>.GetInstance(maximumKnownCount, out var collector);

    for (int i = 0; i < maximumKnownCount; i++)
    {
        collector.Add(CombineKind(valA[i], valB[i]));
    }

    return PropertySetAbstractValue.GetInstance(collector);
}

