void handleNamespace(INamespaceSymbol ns)
{
    foreach (INamespaceOrTypeSymbol member in ns.GetMembers())
    {
        if (member.Kind == SymbolKind.Namespace)
        {
            handleNamespace((INamespaceSymbol)member);
        }
        else if (ns.IsGlobalNamespace)
        {
            includeRootNamespace = true;
        }
        else if (!member.IsImplicitlyDeclared)
        {
            namespacesWithTypeElements.Add(ns);
        }
    }
}

