private static int ComputeMaintainabilityScore(ComputationalComplexityMetrics computationComplexityMetrics, int cycleComplexity)
{
    double computationalComplexityVolume = Math.Max(0.0, Math.Log(computationComplexityMetrics.Volume));   //avoid Log(0) = -Infinity
    double logEffectiveLinesOfCode = Math.Max(0.0, Math.Log(computationComplexityMetrics.EffectiveLinesOfCode));          //avoid Log(0) = -Infinity
    return MetricsHelper.NormalizeAndRoundMaintainabilityIndex(
        171 - 5.2 * computationalComplexityVolume - 0.23 * cycleComplexity - 16.2 * logEffectiveLinesOfCode
    );
}

public static Task<CodeAnalysisMetricData> CalculateAsync(Compilation compilation, CancellationToken cancelToken)
{
    if (compilation == null)
    {
        throw new ArgumentNullException(nameof(compilation));
    }

    return CalculateAsync(compilation.Assembly, new CodeMetricsAnalysisContext(compilation, cancelToken));
}

void trackOperator(IOperation op)
{
    operatorUsageTotal++;
    distinctOperatorKindsBuilder ??= ImmutableHashSet.CreateBuilder<OperationKind>();
    distinctOperatorKindsBuilder.Add(op.Kind);
}

internal static void AddAssociatedNamedTypes(ImmutableHashSet<INamedTypeSymbol>.Builder builder, WellKnownTypeProvider knownTypeProvider,
        ITypeSymbol associatedType)
{
    AddAssociatedNamedTypesCore(builder, associatedType, knownTypeProvider);
}

internal static void ExcludeContainingTypes(ISymbol symbol, ImmutableHashSet<INamedTypeSymbol>.Builder associatedTypesBuilder)
{
    var typeSymbol = symbol as INamedTypeSymbol ?? symbol.ContainingType;
    while (typeSymbol != null)
    {
        associatedTypesBuilder.Remove(typeSymbol);
        typeSymbol = typeSymbol.ContainingType;
    }
}

internal static ImmutableArray<IParameterSymbol> ObtainParameters(this ISymbol member)
{
    return member.Kind switch
    {
        SymbolKind.Method => ((IMethodSymbol)member).Parameters,
        SymbolKind.Property => ((IPropertySymbol)member).Parameters,
        _ => ImmutableArray<IParameterSymbol>.Empty,
    };
}

public SemanticModelCache(Compilation compilation)
{
    Compilation = compilation;
